namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string InstructorName { get; set; }
    public required string InstructorBio { get; set; }
    public int DepartmentId { get; set; }
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public required string Name { get; set; }
    public required string Abbreviation { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]+$", ErrorMessage = "Student ID must be alphanumeric.")]
    [StringLength(20)]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
        new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
        new() { Id = 3, Name = "Physics", Abbreviation = "PHYS" },
        new() { Id = 4, Name = "English", Abbreviation = "ENGL" },
        new() { Id = 5, Name = "History", Abbreviation = "HIST" },
    ];

    private readonly List<Course> _courses;

    public CatalogService()
    {
        _courses =
        [
            new()
            {
                Id = 1, Code = "CS 101", Title = "Introduction to Computer Science",
                Description = "A broad introduction to the field of computer science covering computational thinking, basic algorithms, data representation, and an overview of programming concepts. Ideal for students with no prior experience.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, IsFeatured = true,
                InstructorName = "Dr. Alice Chen",
                InstructorBio = "Dr. Chen holds a Ph.D. from MIT and has over 15 years of experience teaching introductory CS. Her research focuses on CS education and curriculum design."
            },
            new()
            {
                Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms",
                Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (sorting, searching, dynamic programming). Emphasis on time and space complexity analysis.",
                Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", DepartmentId = 1, IsFeatured = true,
                InstructorName = "Dr. Robert Kim",
                InstructorBio = "Dr. Kim is an ACM Distinguished Educator with publications in algorithm optimization and competitive programming pedagogy."
            },
            new()
            {
                Id = 3, Code = "CS 310", Title = "Database Systems",
                Description = "Covers relational database theory, SQL, normalization, indexing, query optimization, and an introduction to NoSQL databases. Includes a semester-long project building a real-world database application.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", DepartmentId = 1, IsFeatured = false,
                InstructorName = "Prof. Maria Santos",
                InstructorBio = "Prof. Santos spent 10 years in industry at Oracle and Microsoft before joining academia. She specializes in distributed database systems."
            },
            new()
            {
                Id = 4, Code = "MATH 151", Title = "Calculus I",
                Description = "Limits, continuity, derivatives of single-variable functions, and applications of differentiation. Provides the mathematical foundation for science and engineering programs.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, IsFeatured = true,
                InstructorName = "Dr. James Okafor",
                InstructorBio = "Dr. Okafor is a two-time recipient of the University Teaching Excellence Award. He has authored three calculus textbooks used nationwide."
            },
            new()
            {
                Id = 5, Code = "MATH 252", Title = "Linear Algebra",
                Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications. Essential for students pursuing advanced mathematics, physics, or data science.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", DepartmentId = 2, IsFeatured = false,
                InstructorName = "Dr. Sarah Lin",
                InstructorBio = "Dr. Lin's research in computational linear algebra has been published in leading journals. She brings real-world applications into every lecture."
            },
            new()
            {
                Id = 6, Code = "PHYS 101", Title = "General Physics I",
                Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions where students design and conduct experiments. Calculus-based approach.",
                Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Thu Lab 2:00–4:00 PM", DepartmentId = 3, IsFeatured = true,
                InstructorName = "Dr. Elena Petrova",
                InstructorBio = "Dr. Petrova is a former CERN researcher whose work on particle physics informs her engaging teaching style. She emphasizes hands-on experimentation."
            },
            new()
            {
                Id = 7, Code = "PHYS 220", Title = "Electromagnetism",
                Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves. Builds on General Physics I with deeper mathematical treatment.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", DepartmentId = 3, IsFeatured = false,
                InstructorName = "Dr. David Park",
                InstructorBio = "Dr. Park has 20 years of teaching experience and conducts research in applied electromagnetics and antenna design."
            },
            new()
            {
                Id = 8, Code = "ENGL 110", Title = "Academic Writing",
                Description = "Develops critical reading and analytical writing skills through essay composition, peer review, and revision. Focus on argumentation, evidence, and academic conventions.",
                Credits = 3, Schedule = "Mon/Wed 9:00–10:15 AM", DepartmentId = 4, IsFeatured = false,
                InstructorName = "Prof. Rachel Green",
                InstructorBio = "Prof. Green has published extensively on rhetoric and composition. She has directed the University Writing Center for eight years."
            },
            new()
            {
                Id = 9, Code = "ENGL 240", Title = "American Literature",
                Description = "Survey of American literature from the colonial period to the present, exploring major authors, literary movements, and cultural contexts.",
                Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", DepartmentId = 4, IsFeatured = false,
                InstructorName = "Dr. Thomas Wright",
                InstructorBio = "Dr. Wright specializes in 20th-century American fiction and has published two books on the works of Toni Morrison and James Baldwin."
            },
            new()
            {
                Id = 10, Code = "HIST 101", Title = "World History to 1500",
                Description = "A global survey of human civilizations from ancient Mesopotamia through the late medieval period. Covers political, social, economic, and cultural developments.",
                Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 5, IsFeatured = false,
                InstructorName = "Dr. Amara Johnson",
                InstructorBio = "Dr. Johnson is an expert in ancient and medieval history with archaeological fieldwork experience across three continents."
            },
            new()
            {
                Id = 11, Code = "HIST 205", Title = "Modern European History",
                Description = "Europe from the French Revolution to the present day, examining nationalism, industrialization, world wars, the Cold War, and European integration.",
                Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", DepartmentId = 5, IsFeatured = false,
                InstructorName = "Dr. Friedrich Bauer",
                InstructorBio = "Dr. Bauer earned his doctorate from the University of Vienna and brings a European perspective to his teaching of modern history."
            },
            new()
            {
                Id = 12, Code = "CS 450", Title = "Machine Learning",
                Description = "Supervised and unsupervised learning, neural networks, deep learning fundamentals, and practical applications using Python. Includes hands-on projects with real datasets.",
                Credits = 3, Schedule = "Tue/Thu 3:30–4:45 PM", DepartmentId = 1, IsFeatured = true,
                InstructorName = "Dr. Wei Zhang",
                InstructorBio = "Dr. Zhang previously led ML research at Google Brain. Her current work focuses on explainable AI and fairness in machine learning systems."
            },
        ];
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.Code).ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).OrderBy(c => c.Code).ToList();
}

