@page "/enroll"

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>
<p>Fill out the form below to submit an enrollment request. You will receive confirmation from the registrar's office.</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@Model.FullName</strong> (ID: @Model.StudentId). Your enrollment request for
            <strong>@(SelectedCourse?.Code) — @(SelectedCourse?.Title)</strong> has been received.</p>
        <hr />
        <p class="mb-0">The registrar's office will process your request and send a confirmation to your university email.</p>
    </div>
    <a href="enroll" class="btn btn-primary">Submit Another Request</a>
}
else
{
    <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" class="mt-3">
        <DataAnnotationsValidator />
        <AntiforgeryToken />

        <div class="row">
            <div class="col-md-6">
                <div class="mb-3">
                    <label for="fullName" class="form-label">Full Name</label>
                    <InputText id="fullName" class="form-control" @bind-Value="Model.FullName" />
                    <ValidationMessage For="() => Model.FullName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" placeholder="e.g. S12345" />
                    <ValidationMessage For="() => Model.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                        <option value="0">— Select a course —</option>
                        @foreach (var course in AllCourses)
                        {
                            <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.CourseId" />
                </div>

                <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
            </div>
        </div>
    </EditForm>
}

@code {
    [Inject] public CatalogService Catalog { get; set; } = default!;

    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private List<Course> AllCourses = [];
    private Course? SelectedCourse;
    private bool Submitted;

    protected override void OnInitialized()
    {
        AllCourses = Catalog.GetCourses();

        // Pre-select course if linked from course detail page
        if (!Submitted && CourseId.HasValue && Model.CourseId == 0)
            Model.CourseId = CourseId.Value;
    }

    private void HandleSubmit()
    {
        SelectedCourse = Catalog.GetCourse(Model.CourseId);
        Submitted = true;
    }
}

